      var pe = into(G.per, c.box3(2.6, 0.6, 2, GREEN, [6, 0.3, 3], iP)); into(G.per, c.label('Закавказье', [6, 1.6, 3], 0.4, '#9be3bf'));
      arrow(c, [0, 0.5, -2.2], [0, 0.5, -4.8], WHITE, iF, G.fin); arrow(c, [-2.1, 0.5, 1.2], [-4.7, 0.5, 2.6], WHITE, iTu, G.tur); arrow(c, [2.1, 0.5, 1.2], [4.7, 0.5, 2.6], WHITE, iP, G.per);
